alter table public.trips
add column if not exists distance double precision;

update public.trips
set distance = case tripid
    when '60000000-0000-0000-0000-000000000001'::uuid then 281
    when '60000000-0000-0000-0000-000000000002'::uuid then 244
    when '60000000-0000-0000-0000-000000000003'::uuid then 53
    when '60000000-0000-0000-0000-000000000004'::uuid then 211
    when '61000000-0000-0000-0000-000000000001'::uuid then 281
    when '61000000-0000-0000-0000-000000000002'::uuid then 244
    when '61000000-0000-0000-0000-000000000003'::uuid then 53
    when '61000000-0000-0000-0000-000000000004'::uuid then 211
    when '61000000-0000-0000-0000-000000000005'::uuid then 135
    when '61000000-0000-0000-0000-000000000006'::uuid then 536
    when '61000000-0000-0000-0000-000000000007'::uuid then 112
    when '61000000-0000-0000-0000-000000000008'::uuid then 28
    when '61000000-0000-0000-0000-000000000009'::uuid then 113
    when '61000000-0000-0000-0000-000000000010'::uuid then 90
    when '61000000-0000-0000-0000-000000000011'::uuid then 82
    when '61000000-0000-0000-0000-000000000012'::uuid then 37
    else distance
end
where tripid in (
    '60000000-0000-0000-0000-000000000001'::uuid,
    '60000000-0000-0000-0000-000000000002'::uuid,
    '60000000-0000-0000-0000-000000000003'::uuid,
    '60000000-0000-0000-0000-000000000004'::uuid,
    '61000000-0000-0000-0000-000000000001'::uuid,
    '61000000-0000-0000-0000-000000000002'::uuid,
    '61000000-0000-0000-0000-000000000003'::uuid,
    '61000000-0000-0000-0000-000000000004'::uuid,
    '61000000-0000-0000-0000-000000000005'::uuid,
    '61000000-0000-0000-0000-000000000006'::uuid,
    '61000000-0000-0000-0000-000000000007'::uuid,
    '61000000-0000-0000-0000-000000000008'::uuid,
    '61000000-0000-0000-0000-000000000009'::uuid,
    '61000000-0000-0000-0000-000000000010'::uuid,
    '61000000-0000-0000-0000-000000000011'::uuid,
    '61000000-0000-0000-0000-000000000012'::uuid
);
